/* Where Earth has land. EARTH_LAND: the whole globe, one bit per half degree, north to south, west to east.
   INDIA_LAND: South Asia (60 to 100 degrees east, 40 to 0 degrees north), one bit per tenth of a degree. */
window.EARTH_LAND = { w: 720, h: 360, bits: "" };
window.INDIA_LAND = { w: 400, h: 400, lon0: 60, lat0: 40, step: .1, bits: "" };
